function validate([version1, version2]) {
  for (const [name, version] of [['version1', version1], ['version2', version2]]) {
    if (typeof version !== 'string' || version.length < 1 || version.length > 500) return `${name} needs 1 to 500 characters.`;
    if (!/^\d+(\.\d+)*$/.test(version)) return `${name} must be digit runs separated by single dots.`;
    for (const part of version.split('.')) {
      const digits = part.replace(/^0+(?=\d)/, '');
      if (digits.length > 10 || Number(digits) > 2147483647) return `Every revision of ${name} must fit in a 32-bit integer.`;
    }
  }
  return null;
}

