    let revision2 = 0;
    while (j < version2.length && version2[j] !== '.') {
      revision2 = revision2 * 10 + Number(version2[j]);
      j++;
    }
    if (revision1 < revision2) return -1;
    if (revision1 > revision2) return 1;
    i++;
    j++;
  }
