function compareVersion(version1, version2) {
  const parts1 = version1.split('.').map(part => parseInt(part, 10));
  const parts2 = version2.split('.').map(part => parseInt(part, 10));
  const length = Math.max(parts1.length, parts2.length);
  while (parts1.length < length) parts1.push(0);
  while (parts2.length < length) parts2.push(0);
  for (let k = 0; k < length; k++) {
    if (parts1[k] !== parts2[k]) return parts1[k] < parts2[k] ? -1 : 1;
  }
  return 0;
}

