function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const small = () => int(0, 12);
  const write = values => values.map(v => '0'.repeat(rand() < 0.25 ? int(1, 2) : 0) + v).join('.');
  for (;;) {
    const count = size === 'large' ? int(60, 110) : int(1, 4);
    const values = Array.from({ length: count }, () => (size === 'large' && rand() < 0.05 ? int(0, 2147483647) : small()));
    let other = values.slice();
    const mode = rand();
    if (mode < 0.3) other[int(0, other.length - 1)] = small();
    else if (mode < 0.5) { const extra = int(1, 3); for (let k = 0; k < extra; k++) other.push(rand() < 0.6 ? 0 : int(0, 3)); }
    else if (mode < 0.65) other = other.slice(0, int(1, other.length));
    else if (mode < 0.8) other = Array.from({ length: size === 'large' ? count : int(1, 4) }, small);
    let version1 = write(values);
    let version2 = write(other);
    if (rand() < 0.5) [version1, version2] = [version2, version1];
    if (version1.length <= 500 && version2.length <= 500) return [version1, version2];
  }
}
